function [c] = unit_counts(u, s)
%UNIT_COUNTS  A Sun or Earth sensor's unit vector u (body) as its registers' counts (Q15).
%   u: real[1][3] (passed a plain number)
%   s: EmuScale (passed rec)
%   returns c: int[3] (passed a whole number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    c = zeros(3, 1);
    c = zeros(3, 1);
    for i = (0):((3) - 1)
        c((i) + 1) = asils.models.emucodec.emu_count((u((i) + 1) / s.unit), s.lo16, s.hi16);
    end
end
